import{_ as t,o as d,c as i,a3 as n}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Adressbuch einrichten","description":"Ein Firmen-Adressbuch in der App – Kontakte aus einem Grid, mit Suche, Abteilungsfilter und Offline-Kopie.","frontmatter":{"title":"Adressbuch einrichten","description":"Ein Firmen-Adressbuch in der App – Kontakte aus einem Grid, mit Suche, Abteilungsfilter und Offline-Kopie."},"headers":[],"relativePath":"apptiveteams/adressbuch.md","filePath":"apptiveteams/adressbuch.md","lastUpdated":1788846304000}'),r={name:"apptiveteams/adressbuch.md"};function a(o,e,s,l,c,h){return d(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adressbuch-einrichten" tabindex="-1">Adressbuch einrichten <a class="header-anchor" href="#adressbuch-einrichten" aria-label="Permalink to &quot;Adressbuch einrichten&quot;">​</a></h1><p>Ein Tab vom Typ <code>AddressBook</code> zeigt ein Firmen-Adressbuch in der App: Kontakte mit Foto, Telefon, E-Mail und Anschrift, eine Suche und ein Filter nach Abteilung. Die Kontakte sind Zeilen in einem Grid Ihres ApptiveGrid-Kontos. Optional erscheinen auch Firmen als eigene Einträge, mit Sprung von der Firma zu ihren Personen und zurück.</p><p>Die App legt pro Team eine <strong>Offline-Kopie</strong> der Kontakte auf dem Gerät an. Das Adressbuch des Telefons bleibt unberührt, die App fragt keine Kontakte-Berechtigung ab.</p><h2 id="die-tabs-zeile" tabindex="-1">Die Tabs-Zeile <a class="header-anchor" href="#die-tabs-zeile" aria-label="Permalink to &quot;Die Tabs-Zeile&quot;">​</a></h2><p>Im Grid <code>tabs</code> des Team Space ergänzen Sie eine Zeile:</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Wert</th></tr></thead><tbody><tr><td><code>title</code></td><td>zum Beispiel „Kontakte“</td></tr><tr><td><code>icon</code></td><td>einfarbiges SVG</td></tr><tr><td><code>type</code></td><td><code>AddressBook</code></td></tr><tr><td><code>gridUri</code></td><td>Verknüpfung auf das Kontakte-Grid oder eine Ansicht darauf</td></tr><tr><td><code>uri</code></td><td>alternativ: Link einer geteilten Ansicht</td></tr></tbody></table><p>Sie brauchen <strong>eines</strong> der beiden Felder. <code>gridUri</code> zeigt auf ein Grid oder eine Ansicht im Team Space, das die Mitglieder sehen dürfen. Liegen die Kontakte in einem Space, auf den die Belegschaft keinen Zugriff hat, teilen Sie dort eine Ansicht per Link und tragen den Link in <code>uri</code> ein. Sind beide gesetzt, gilt <code>gridUri</code>. → <a href="/ansichten/ansicht-teilen">Ansicht teilen</a></p><h2 id="das-kontakte-grid" tabindex="-1">Das Kontakte-Grid <a class="header-anchor" href="#das-kontakte-grid" aria-label="Permalink to &quot;Das Kontakte-Grid&quot;">​</a></h2><p>Nur <code>lastName</code> ist Pflicht. Alles andere erscheint, wenn es da ist; fehlende Angaben werden einfach nicht angezeigt. Die Namen der Felder sind frei, die <strong>Keys</strong> müssen genau stimmen. → <a href="/apptiveteams/team-space#keys-wie-die-app-ihre-grids-findet">Keys vergeben</a></p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>lastName</code></td><td>Text</td><td>ja</td><td>Nachname</td></tr><tr><td><code>firstName</code></td><td>Text</td><td>nein</td><td>Vorname</td></tr><tr><td><code>company</code></td><td>Text oder Verknüpfung</td><td>nein</td><td>Firma; als Verknüpfung auf ein Firmen-Grid werden Firmen zu eigenen Einträgen, siehe unten</td></tr><tr><td><code>department</code></td><td>Text oder Einzelauswahl</td><td>nein</td><td>Abteilung, Team oder Standort; danach filtert die App</td></tr><tr><td><code>role</code></td><td>Text</td><td>nein</td><td>Position oder Funktion</td></tr><tr><td><code>phone</code></td><td>Telefonnummer</td><td>nein</td><td>Festnetz oder Durchwahl</td></tr><tr><td><code>mobile</code></td><td>Telefonnummer</td><td>nein</td><td>Mobilnummer</td></tr><tr><td><code>email</code></td><td>E-Mail</td><td>nein</td><td>E-Mail-Adresse</td></tr><tr><td><code>photo</code></td><td>Anhang</td><td>nein</td><td>Foto; das erste Bild wird verwendet</td></tr><tr><td><code>address</code></td><td>Adresse oder Text</td><td>nein</td><td>Anschrift</td></tr><tr><td><code>notes</code></td><td>Text</td><td>nein</td><td>Notizen, zum Beispiel Erreichbarkeit</td></tr><tr><td><code>active</code></td><td>Häkchen</td><td>nein</td><td>Nicht angehakte Zeilen werden ausgeblendet. Fehlt das Feld, sind alle sichtbar</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Ausgeschiedene ohne Löschen ausblenden</p><p>Mit <code>active</code> blenden Sie Kontakte aus, ohne die Zeile zu löschen. Eine gefilterte Ansicht als Quelle erfüllt denselben Zweck und erlaubt zusätzlich, Spalten vor der App zu verbergen.</p></div><h2 id="optional-firmen-als-eigene-eintrage" tabindex="-1">Optional: Firmen als eigene Einträge <a class="header-anchor" href="#optional-firmen-als-eigene-eintrage" aria-label="Permalink to &quot;Optional: Firmen als eigene Einträge&quot;">​</a></h2><p>Machen Sie <code>company</code> zu einer <strong>Verknüpfung</strong> auf ein zweites Grid, erscheinen dessen Zeilen im Adressbuch als Firmen. Von einer Firma springen Sie zu ihren Personen und von einer Person zu ihrer Firma. Das Firmen-Grid muss nirgends eingetragen werden, seine Adresse steht in der Verknüpfung.</p><table tabindex="0"><thead><tr><th>Feld-Key</th><th>Feldtyp</th><th>Pflicht</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>name</code></td><td>Text</td><td>ja</td><td>Name der Firma</td></tr><tr><td><code>phone</code></td><td>Telefonnummer</td><td>nein</td><td>Zentrale</td></tr><tr><td><code>email</code></td><td>E-Mail</td><td>nein</td><td>zentrale Adresse</td></tr><tr><td><code>website</code></td><td>Weblink oder Text</td><td>nein</td><td>Website</td></tr><tr><td><code>address</code></td><td>Adresse oder Text</td><td>nein</td><td>Anschrift</td></tr><tr><td><code>notes</code></td><td>Text</td><td>nein</td><td>Notizen</td></tr><tr><td><code>logo</code></td><td>Anhang</td><td>nein</td><td>Logo; das erste Bild wird verwendet</td></tr><tr><td><code>active</code></td><td>Häkchen</td><td>nein</td><td>wie bei den Kontakten</td></tr></tbody></table><p>Bleibt <code>company</code> ein Textfeld, gibt es keine Firmeneinträge; alles andere funktioniert unverändert.</p><h2 id="so-arbeitet-die-app" tabindex="-1">So arbeitet die App <a class="header-anchor" href="#so-arbeitet-die-app" aria-label="Permalink to &quot;So arbeitet die App&quot;">​</a></h2><ul><li>Beim Öffnen des Tabs lädt die App die Kontakte und speichert sie als Offline-Kopie pro Team. Ohne Verbindung zeigt sie den zuletzt geladenen Stand.</li><li>Suche und Abteilungsfilter arbeiten auf der Kopie, also auch offline.</li><li>Beim Abmelden werden die Kopien aller Teams vom Gerät gelöscht.</li><li>Fehlt der Pflicht-Key <code>lastName</code>, zeigt der Tab statt Kontakten einen Hinweis mit den Feldern, die das Grid tatsächlich liefert.</li></ul><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/ansichten/ansicht-teilen">Ansicht teilen</a></li><li><a href="/apptiveteams/fehlerbehebung">Tipps und Fehlerbehebung</a></li></ul>',19)])])}const b=t(r,[["render",a]]);export{p as __pageData,b as default};
